def export_dataset() -> None:
    target = ROOT / "data" / "infrastructures.json"
    normalized = normalize_records(DATASET)
    target.write_text(
        json.dumps(normalized, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    print(f"Exportados {len(normalized)} registros para {target}")


if __name__ == "__main__":
    export_dataset()
